const BANKS = { quimica:QUIMICA, biologia:BIOLOGIA, programacion:PROGRAMACION };

const QDUR = Number(process.env.QDUR)||10;
const REVEAL_MS = Number(process.env.REVEAL_MS)||1600;
const ADVANCE_MS = Number(process.env.ADVANCE_MS)||5200;
const RULETA_MS = Number(process.env.RULETA_MS)||2200;
const META = Number(process.env.META)||100;
function shuffle(a){ a=a.slice(); for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); const t=a[i]; a[i]=a[j]; a[j]=t; } return a; }
function pick(a){ return a[Math.floor(Math.random()*a.length)]; }

class Player extends Schema {}
defineTypes(Player, { name:"string", anim:"string", role:"string", connected:"boolean" });
class RaceState extends Schema {
  constructor(){ super(); this.players=new MapSchema(); this.status="waiting"; this.hostName=""; this.isPrivate=false; this.code=""; this.materia=""; }
}
defineTypes(RaceState, { status:"string", hostName:"string", isPrivate:"boolean", code:"string", materia:"string", players:{ map: Player } });

const codeToRoom = new Map();
const publicRooms = new Map();
const MAXP = 5;

class RaceRoom extends Room {
  onCreate(options){
    options = options || {};
    this.maxClients = 20;
    const st = new RaceState();
    st.hostName = options.name ? String(options.name).slice(0,16) : "Anfitrion";
    st.isPrivate = !!options.isPrivate;
    st.code = options.code ? String(options.code) : "";
    st.materia = (options.materia && BANKS[options.materia]!==undefined) ? options.materia : (options.materia==="prehistoria"?"prehistoria":"quimica");
    if (options.materia==="prehistoria") st.materia="prehistoria";
    this.setState(st);
    this.materia = st.materia;
    this.hostSessionId = null;
    this.gTimer = null;
    if (st.isPrivate){
      if (!st.code || codeToRoom.has(st.code)) throw new Error("CODE_TAKEN");
      this.setPrivate(true); codeToRoom.set(st.code, this.roomId);
    }
    this.refreshList();

    this.onMessage("pickAvatar", (client, msg)=>{
      if (this.state.status!=="waiting") return;
      const sid=client.sessionId; const p=this.state.players.get(sid);
      if (!p || p.role!=="player") return;
      const anim = msg && String(msg.anim||"");
      if (!anim) return;
      let taken=false; this.state.players.forEach((pp,s)=>{ if(s!==sid && pp.anim===anim) taken=true; });
      if (taken) return;
      p.anim = anim; this.refreshList();
    });

    this.onMessage("ready", (client)=>{
      if (client.sessionId!==this.hostSessionId) return;
      if (this.countPlayers()<2) return;
      let allAv=true; this.state.players.forEach(pp=>{ if(pp.role==="player" && !pp.anim) allAv=false; });
      if (!allAv) return;
      this.state.status="playing"; this.lock(); this.refreshList();
      this.broadcast("start", {});
      this.startGame();
    });

    this.onMessage("answer", (client, msg)=>{
      if (!this.qList || !msg) return;
      const i=msg.index; if (i!==this.qIndex) return;
      const sid=client.sessionId;
      if (this.pos[sid]===undefined) return;
      if (this.qAns[sid]) return;
      this.qAns[sid]=true;
      const q=this.qList[i];
      const correct = (msg.option===q.correct);
      let secs=0;
      if (correct){ const left=Math.max(0, QDUR-(Date.now()-this.qSentAt)/1000); secs=Math.max(0,Math.min(QDUR,Math.ceil(left))); this.roundGain[sid]+=secs; }
      client.send("answerResult", { index:i, correct:correct, correctIndex:q.correct, secs:secs });
      let all=true; this.pOrder.forEach(s=>{ if(!this.qAns[s]) all=false; });
      if (all){ this.clearT(); this.questionReveal(i); }
    });
  }

  onAuth(client, options){
    if (this.state.isPrivate){ if(!options || String(options.code)!==this.state.code) throw new Error("BAD_CODE"); }
    return true;
  }
  onJoin(client, options){
    options=options||{};
    const p=new Player();
    p.name = options.name ? String(options.name).slice(0,16) : "Jugador";
    p.anim=""; p.connected=true;
    if (this.countPlayers()<MAXP && this.state.status==="waiting"){
      p.role="player"; if (this.hostSessionId===null) this.hostSessionId=client.sessionId;
    } else p.role="spectator";
    this.state.players.set(client.sessionId, p);
    this.refreshList();
  }
  onLeave(client){
    const sid=client.sessionId;
    this.state.players.delete(sid);
    if (this.state.status==="playing" && this.pos && this.pos[sid]!==undefined){
      delete this.pos[sid];
      if (this.pOrder){ const k=this.pOrder.indexOf(sid); if(k>=0) this.pOrder.splice(k,1); }
      this.broadcast("playerLeft", {});
      if (!this.pOrder || this.pOrder.length<1){ this.clearT(); this.state.status="finished"; this.refreshList(); }
      else if (this.qAns){ let all=true; this.pOrder.forEach(s=>{ if(!this.qAns[s]) all=false; }); if(all && this.qList && this.qIndex!=null){ this.clearT(); this.questionReveal(this.qIndex); } }
    }
    if (sid===this.hostSessionId){ this.hostSessionId=null; this.state.players.forEach((pp,s)=>{ if(this.hostSessionId===null && pp.role==="player") this.hostSessionId=s; }); }
    this.refreshList();
  }
  onDispose(){ this.clearT(); if(this.state.isPrivate && this.state.code) codeToRoom.delete(this.state.code); publicRooms.delete(this.roomId); }

  countPlayers(){ let n=0; this.state.players.forEach(p=>{ if(p.role==="player") n++; }); return n; }
  countSpectators(){ let n=0; this.state.players.forEach(p=>{ if(p.role==="spectator") n++; }); return n; }
  clearT(){ if(this.gTimer){ clearTimeout(this.gTimer); this.gTimer=null; } }
  refreshList(){
    const info={ hostName:this.state.hostName, players:this.countPlayers(), spectators:this.countSpectators(), status:this.state.status, materia:this.state.materia };
    this.setMetadata(info);
    if (!this.state.isPrivate) publicRooms.set(this.roomId, info);
  }

  // ===== PARTIDA =====
  startGame(){
    this.pOrder=[]; this.pos={}; this.pinfo={};
    this.state.players.forEach((p,sid)=>{ if(p.role==="player"){ this.pOrder.push(sid); this.pos[sid]=0; this.pinfo[sid]={name:p.name,anim:p.anim}; } });
    this.round=0; this.usedThemes={};
    this.beginRound();
  }
  beginRound(){
    this.round++;
    if (this.materia==="prehistoria"){
      this.theme="Dinosaurios";
      this.broadcast("roundStart", { round:this.round });
      this.clearT(); this.gTimer=setTimeout(()=>this.startQuestions(), 900);
    } else {
      const T=BANKS[this.materia].TOPICS;
      let avail=T.filter(t=>!this.usedThemes[t]);
      if (avail.length===0){ this.usedThemes={}; avail=T.slice(); }
      this.theme=pick(avail); this.usedThemes[this.theme]=1;
      this.broadcast("ruleta", { round:this.round, theme:this.theme });
      this.clearT(); this.gTimer=setTimeout(()=>this.startQuestions(), RULETA_MS);
    }
  }
  buildQuestions(){
    if (this.materia==="prehistoria"){
      return shuffle(DINOS).slice(0,4).map(d=>{ const o=shuffle([d.nombre,d.d1,d.d2]); return {img:d.id, ask:"\u00bfQu\u00e9 dinosaurio es?", options:o, correct:o.indexOf(d.nombre)}; });
    } else {
      const bank=BANKS[this.materia].QBANK[this.theme]||[];
      return shuffle(bank).slice(0,4).map(q=>{ const idx=shuffle([0,1,2]); const o=idx.map(i=>q.o[i]); return {stage:q.s, ask:q.a, options:o, correct:idx.indexOf(q.c)}; });
    }
  }
  startQuestions(){
    this.qList=this.buildQuestions();
    this.roundGain={}; this.pOrder.forEach(s=>this.roundGain[s]=0);
    this.qIndex=0; this.sendQuestion(0);
  }
  sendQuestion(i){
    this.qIndex=i; const q=this.qList[i];
    this.qSentAt=Date.now(); this.qAns={};
    this.broadcast("question", { index:i, total:4, theme:this.theme, stage:q.stage||null, img:q.img||null, ask:q.ask, options:q.options, duration:QDUR });
    this.clearT(); this.gTimer=setTimeout(()=>this.questionReveal(i), (QDUR*1000)+400);
  }
  questionReveal(i){
    const q=this.qList[i];
    this.broadcast("reveal", { index:i, correctIndex:q.correct });
    this.clearT(); this.gTimer=setTimeout(()=>{ this.qIndex++; if(this.qIndex<4) this.sendQuestion(this.qIndex); else this.endRound(); }, REVEAL_MS);
  }
  endRound(){
    const arr=[];
    this.pOrder.forEach(sid=>{ this.pos[sid]+=(this.roundGain[sid]||0); arr.push({name:this.pinfo[sid].name, anim:this.pinfo[sid].anim, gain:this.roundGain[sid]||0, pos:this.pos[sid]}); });
    this.broadcast("advance", { round:this.round, theme:this.theme, players:arr });
    let maxp=0; this.pOrder.forEach(sid=>{ if(this.pos[sid]>maxp) maxp=this.pos[sid]; });
    this.clearT();
    this.gTimer=setTimeout(()=>{ if(maxp>=META) this.gameOver(); else this.beginRound(); }, ADVANCE_MS);
  }
  gameOver(){
    this.clearT();
    const standings=this.pOrder.map(sid=>({name:this.pinfo[sid].name, anim:this.pinfo[sid].anim, pos:Math.round(this.pos[sid])}));
    standings.sort((a,b)=>b.pos-a.pos);
    this.broadcast("gameOver", { standings:standings });
    this.state.status="finished"; this.refreshList();
  }
}

const app = express();
app.use(cors());
app.get("/", (_req,res)=>res.send("Carreras - servidor OK"));
app.get("/rooms", (req,res)=>{
  const mat=req.query.materia;
  const list=[];
  publicRooms.forEach((info,roomId)=>{ if(info.status==="waiting" && (!mat || info.materia===mat)) list.push({roomId, hostName:info.hostName, players:info.players, spectators:info.spectators, materia:info.materia}); });
  res.json(list);
});
app.get("/find/:code", (req,res)=>{ const id=codeToRoom.get(String(req.params.code)); if(!id) return res.status(404).json({error:"NOT_FOUND"}); res.json({roomId:id}); });
app.use("/colyseus", monitor());
const port = Number(process.env.PORT)||2567;
const server = http.createServer(app);
const gameServer = new Server({ transport: new WebSocketTransport({ server }) });
gameServer.define("race", RaceRoom);
gameServer.listen(port);
console.log("Servidor Carreras en puerto "+port);
